<?php use App\Services\{Publisher,History,Attachments}; ?>
<div class="surface table-responsive"><table class="table"><thead><tr><th>Announcement</th><th>Module</th><th>Created by</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($historyRows as $a): $link=Publisher::remoteLink($a); ?><tr <?= $showDelete?'data-history-announcement="'.e($a['id']).'"':'' ?>><td><strong><?= e($a['title']) ?></strong><small class="d-block text-secondary mt-1"><?= e($a['created_at']) ?> UTC</small><?php if($a['body']): ?><details class="mt-2"><summary>Read announcement</summary><p class="preserve-lines mt-3"><?= e($a['body']) ?></p></details><?php endif; ?><?php if($a['image_path']): ?><details class="mt-2"><summary>View poster</summary><?php foreach(Attachments::all((int)$a['id']) as $poster): ?><img class="history-poster" src="<?= e(local_url('/image?attachment='.$poster['id'])) ?>" alt="<?= e($a['title']) ?>" loading="lazy"><?php endforeach; ?></details><?php endif; ?></td><td><?= $a['type']==='partial'?'Partial update':'Scheduled interruption' ?></td><td><?= e($a['author']) ?></td><td><span class="status-badge"><?= e(Publisher::status($a)) ?></span><?php if($a['wordpress_post_id']): ?><small class="d-block mt-2">WordPress #<?= e($a['wordpress_post_id']) ?></small><?php endif; ?><?php if($a['wordpress_post_id'] && (int)$a['synced_revision']!==(int)$a['revision']): ?><small class="d-block mt-2">Local changes pending</small><?php endif; ?><?php if($a['publish_error']): ?><p class="publish-error mt-2"><?= e($a['publish_error']) ?></p><?php endif; ?></td><td><a class="btn btn-sm btn-outline-secondary mb-2" href="<?= e(local_url('/announcement?id='.$a['id'])) ?>"><?= $a['status']==='failed'?'Review / retry':'Review / publish' ?></a><?php if($link && $a['wordpress_status']==='publish'): ?><a class="text-link d-block mb-2" href="<?= e($link) ?>" target="_blank" rel="noopener noreferrer">View on WordPress ↗</a><?php endif; ?><?php if($showDelete && History::canDelete($user,(int)$a['user_id'])): ?><form method="post" action="<?= e(local_url('/history/delete')) ?>" data-history-form data-kind="delete"><?= csrf() ?><input type="hidden" name="confirmed" value="0"><input type="hidden" name="kind" value="announcement"><input type="hidden" name="id" value="<?= e($a['id']) ?>"><button class="btn btn-sm btn-outline-danger" type="button" data-history-open>Delete</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$historyRows): ?><tr><td colspan="5"><div class="empty-state"><h3>No local history entries</h3><p>Active work is retained separately when history is cleared.</p></div></td></tr><?php endif; ?></tbody></table></div>
